export function completionStats(modules: FirstModule[]) {
  const complete = modules.filter((m) => m.status === "complete").length;
  return { complete, total: modules.length, pct: Math.round((complete / modules.length) * 100) };
}

export type StageProgress = {
  stage: StageId;
  label: string;
  shortLabel: string;
  href: string;
  complete: number;
  total: number;
  pct: number;
};

/** Completion, per stage, in STAGES order. */
export function stageProgress(modules: FirstModule[]): StageProgress[] {
  return STAGES.map((s) => {
    const stageModules = modules.filter((m) => m.stage === s.id);
    const stats = completionStats(stageModules);
    return { stage: s.id, label: s.label, shortLabel: s.shortLabel, href: s.href, ...stats };
  });
}

export type CategoryProgress = {
  category: keyof typeof CATEGORY_META;
  label: string;
  color: string;
  stage: StageId;
  complete: number;
  total: number;
  pct: number;
};

/** Completion, per category, grouped and ordered by the stage each category belongs to. */
export function categoryProgressByStage(
  modules: FirstModule[]
): { stage: StageId; shortLabel: string; categories: CategoryProgress[] }[] {
  return STAGES.map((s) => {
    const stageModules = modules.filter((m) => m.stage === s.id);
    const seen: (keyof typeof CATEGORY_META)[] = [];
    for (const m of stageModules) {
      if (!seen.includes(m.category)) seen.push(m.category);
    }
    const categories = seen.map((cat) => {
      const catModules = stageModules.filter((m) => m.category === cat);
      const stats = completionStats(catModules);
      const meta = CATEGORY_META[cat];
      return { category: cat, label: meta.label, color: meta.color, stage: s.id, ...stats };
    });
    return { stage: s.id, shortLabel: s.shortLabel, categories };
  });
}

/** The stage a category belongs to, derived from the first FIRST that uses it. */
export function stageForCategory(category: keyof typeof CATEGORY_META): StageId | undefined {
  return FIRSTS.find((m) => m.category === category)?.stage;
}
